    """Tuned Best Fit (lo=6, hi=13, penalty=46): the tightest bin wins, but leaving a gap
    strictly between 6 and 13 units costs 46. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 46 * ((r > 6) & (r < 13))

