    """Tuned Best Fit (lo=7, hi=38, penalty=46): the tightest bin wins, but leaving a gap
    strictly between 7 and 38 units costs 46. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 46 * ((r > 7) & (r < 38))

